def vowels_count(s):
    vowels = set('aeiouAEIOU')
    count = sum(1 for char in s if char in vowels)
    if s and s[-1] in 'yY':
        count += 1
    return count

import unittest

class TestVowelsCount(unittest.TestCase):
    def test_examples(self):
        self.assertEqual(vowels_count("abcde"), 2)
        self.assertEqual(vowels_count("ACEDY"), 3)

    def test_vowels_in_middle(self):
        self.assertEqual(vowels_count("hello"), 2)
        self.assertEqual(vowels_count("bicycle"), 2)

    def test_vowels_in_different_cases(self):
        self.assertEqual(vowels_count("AEIOU"), 5)
        self.assertEqual(vowels_count("aeiou"), 5)

    def test_y_at_end(self):
        self.assertEqual(vowels_count("myth"), 0)
        self.assertEqual(vowels_count("mystery"), 2)

    def test_y_not_at_end(self):
        self.assertEqual(vowels_count("rhythms"), 0)
        self.assertEqual(vowels_count("crypt"), 0)

    def test_empty_string(self):
        self.assertEqual(vowels_count(""), 0)

    def test_only_consonants(self):
        self.assertEqual(vowels_count("bcdfg"), 0)

    def test_only_vowels(self):
        self.assertEqual(vowels_count("aei"), 3)
        self.assertEqual(vowels_count("yu"), 2)

if __name__ == "__main__":
    unittest.main()
